args.cmd:
powershell -NoProfile -Command "
# Search for maa-cli in common locations
$paths = @(
    (Join-Path $env:LOCALAPPDATA 'Programs\maa-cli\maa.exe'),
    (Join-Path $env:LOCALAPPDATA 'maa-cli\maa.exe'),
    'maa'
)
$found = $false
foreach ($p in $paths) {
    if ($p -eq 'maa') {
        $cmd = Get-Command maa -ErrorAction SilentlyContinue
        if ($cmd) { Write-Output \"FOUND_PATH=$($cmd.Source)\"; $found = $true; break }
    } elseif (Test-Path $p) {
        Write-Output \"FOUND_PATH=$p\"; $found = $true; break
    }
}
if (-not $found) { Write-Output 'MAA_NOT_FOUND' }
"
